document.addEventListener("DOMContentLoaded", () => {
  const grid = document.getElementById("grid-productos");
  const buscador = document.getElementById("buscador");

  if (!grid) return;

  let productos = [];

  const escapeHtml = (value = "") =>
    String(value)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#039;");

  const imagePath = (producto) => {
    if (!producto.imagen) return producto.imagen_url || "img/placeholder.png";
    return `img/${producto.imagen}`;
  };

  function render(products) {
    grid.innerHTML = "";

    if (!products.length) {
      grid.innerHTML = '<div class="col-12"><p class="text-center text-muted">No se encontraron productos.</p></div>';
      return;
    }

    products.forEach((producto) => {
      const col = document.createElement("div");
      col.className = "col mb-5";
      col.dataset.nombre = [
        producto.nombre,
        producto.descripcion,
        producto.codigo,
        producto.marca,
        producto.categoria,
        producto.subcategoria
      ].filter(Boolean).join(" ").toLowerCase();

      const precio = producto.precio != null
        ? `<span class="text-success fw-bold">$${Number(producto.precio).toFixed(0)}</span>`
        : "";

      col.innerHTML = `
        <div class="card h-100 shadow-sm">
          <img
            class="card-img-top"
            loading="lazy"
            src="${escapeHtml(imagePath(producto))}"
            alt="${escapeHtml(producto.nombre || "Producto Relive")}"
            style="object-fit:contain;width:100%;height:220px;padding:12px;"
            onerror="this.onerror=null;this.src='img/placeholder.png';"
          />
          <div class="card-body p-4">
            <div class="text-center">
              <small class="text-muted">${escapeHtml(producto.categoria || "")} · ${escapeHtml(producto.subcategoria || "")}</small>
              <h5 class="fw-bolder mt-2">${escapeHtml(producto.nombre || "Producto")}</h5>
              ${producto.marca ? `<div class="small text-muted">${escapeHtml(producto.marca)}</div>` : ""}
              ${producto.codigo ? `<div class="small text-muted">Código: ${escapeHtml(producto.codigo)}</div>` : ""}
              <div class="mt-2">${precio}</div>
            </div>
          </div>
        </div>
      `;

      grid.appendChild(col);
    });
  }

  fetch("productos_relive.json")
    .then((response) => {
      if (!response.ok) throw new Error(`No se pudo cargar productos_relive.json (HTTP ${response.status})`);
      return response.json();
    })
    .then((catalogo) => {
      productos = Array.isArray(catalogo) ? catalogo : (catalogo.productos || []);
      render(productos);

      if (buscador) {
        buscador.addEventListener("input", (event) => {
          const query = event.target.value.trim().toLowerCase();
          const filtrados = !query
            ? productos
            : productos.filter((producto) =>
                [
                  producto.nombre,
                  producto.descripcion,
                  producto.codigo,
                  producto.marca,
                  producto.categoria,
                  producto.subcategoria
                ].filter(Boolean).join(" ").toLowerCase().includes(query)
              );

          render(filtrados);
        });
      }
    })
    .catch((error) => {
      console.error(error);
      grid.innerHTML = '<div class="col-12"><p class="text-center text-muted">No se pudo cargar el catálogo.</p></div>';
    });
});